<?php
require __DIR__.'/../includes/bootstrap.php';require_role('admin');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$source=trim($_POST['source_path']??'');$target=trim($_POST['target_url']??'');if($source===''||!filter_var($target,FILTER_VALIDATE_URL))$error='Enter a source path and valid target URL.';else{try{$q=$pdo->prepare($id?'UPDATE redirects SET source_path=?,target_url=?,active=? WHERE id=?':'INSERT INTO redirects(source_path,target_url,active) VALUES(?,?,?)');$id?$q->execute([$source,$target,isset($_POST['active'])?1:0,$id]):$q->execute([$source,$target,1]);header('Location: redirects.php');exit;}catch(Throwable $e){$error='Unable to save redirect.';}}}
if(isset($_GET['delete'])){$q=$pdo->prepare('DELETE FROM redirects WHERE id=?');$q->execute([(int)$_GET['delete']]);header('Location: redirects.php');exit;}$rows=$pdo?$pdo->query('SELECT * FROM redirects ORDER BY created_at DESC')->fetchAll():[];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Redirects</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Redirect management</h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><form method="post" class="card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Source path<input name="source_path" placeholder="/old-page"></label><label>Target URL<input type="url" name="target_url" required placeholder="https://asmraudio.online/new-page"></label><label><input type="checkbox" name="active" checked> Active</label><p><button>Save redirect</button> <a href="dashboard.php">Dashboard</a></p></form><div class="card"><table style="width:100%"><tr><th>Source</th><th>Target</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['source_path'])?></td><td><?=e($r['target_url'])?></td><td><?=((int)$r['active'])?'Active':'Off'?></td><td><a href="?delete=<?=$r['id']?>" onclick="return confirm('Delete redirect?')">Delete</a></td></tr><?php endforeach;?></table></div></main></body></html>
